// FuzzActionKind enumerates the discrete state-machine transitions generated by the fuzzer.
type FuzzActionKind int

const (
	ActionAdmit FuzzActionKind = iota
	ActionStep
	ActionPreempt
	ActionDrain
	ActionSwap
	ActionEvict
	ActionCancel
	ActionResize
)

func (k FuzzActionKind) String() string {
	switch k {
	case ActionAdmit:
		return "Admit"
	case ActionStep:
		return "Step"
	case ActionPreempt:
		return "Preempt"
	case ActionDrain:
		return "Drain"
	case ActionSwap:
		return "Swap"
	case ActionEvict:
		return "Evict"
	case ActionCancel:
		return "Cancel"
	case ActionResize:
		return "Resize"
	default:
		return fmt.Sprintf("Action(%d)", int(k))
	}
}

// FuzzAction represents a concrete operation in the state machine with deterministic arguments.
type FuzzAction struct {
	Kind         FuzzActionKind
	SessionID    string
	PromptTokens []int
	Priority     int
	TargetBlocks int
	Mode         NativePreemptionMode
}

func (a FuzzAction) String() string {
	switch a.Kind {
	case ActionAdmit:
		return fmt.Sprintf("Admit(seq=%s, len=%d, prio=%d)", a.SessionID, len(a.PromptTokens), a.Priority)
	case ActionStep:
		return "Step()"
	case ActionPreempt:
		return fmt.Sprintf("Preempt(mode=%v)", a.Mode)
	case ActionDrain:
		return fmt.Sprintf("Drain(target=%d)", a.TargetBlocks)
	case ActionSwap:
		return fmt.Sprintf("Swap(seq=%s)", a.SessionID)
	case ActionEvict:
		return fmt.Sprintf("Evict(seq=%s)", a.SessionID)
	case ActionCancel:
		return fmt.Sprintf("Cancel(seq=%s)", a.SessionID)
	case ActionResize:
		return fmt.Sprintf("Resize(target=%d)", a.TargetBlocks)
	default:
		return fmt.Sprintf("%v(seq=%s)", a.Kind, a.SessionID)
	}
}

// RequestLifecycleState models the legal state graph for a continuous batching session:
// WAITING -> RUNNING <-> PREEMPTED (swapped/recompute)
// Any active state -> CANCELLED or COMPLETED (terminal states).
type RequestLifecycleState int

const (
	StateUnseen RequestLifecycleState = iota
	StateWaiting
	StateRunning
	StatePreempted
	StateCancelled
	StateCompleted
)

func (s RequestLifecycleState) String() string {
	switch s {
	case StateUnseen:
		return "UNSEEN"
	case StateWaiting:
		return "WAITING"
	case StateRunning:
		return "RUNNING"
	case StatePreempted:
		return "PREEMPTED"
	case StateCancelled:
		return "CANCELLED"
	case StateCompleted:
		return "COMPLETED"
	default:
		return fmt.Sprintf("State(%d)", int(s))
	}
}

// ContinuousBatchStateMachine tracks active sessions, their block allocations, and their lifecycle states.
type ContinuousBatchStateMachine struct {
	mu          sync.Mutex
	cfg         ElasticBlockAllocatorConfig
	allocator   *ElasticBlockAllocator
	maxBlocks   int
	blockTokens int
	maxRunning  int

	// Model tracking
	activeSessions map[string]*fuzzSession
	allSessions    map[string]*fuzzSession
	stepCount      int
}

type fuzzSession struct {
	id            string
	state         RequestLifecycleState
	priority      int
	promptTokens  []int
	emittedTokens []int
	maxGen        int
	ownedBlocks   map[int]bool
	hostKV        []byte
	cancelFunc    context.CancelFunc
	createdStep   int
	lastStep      int
}

func newContinuousBatchStateMachine(initialBlocks, blockTokens, maxRunning int) (*ContinuousBatchStateMachine, error) {
	if blockTokens <= 0 {
		blockTokens = 16
	}
	cfg := ElasticBlockAllocatorConfig{
		InitialBlocks: initialBlocks,
		ModelCfg:      testModelConfig(),
		BlockTokens:   blockTokens,
		VictimSelector: func(activeSequences []ActiveSequenceInfo, neededBlocks int) (string, error) {
			if len(activeSequences) == 0 {
				return "", nil
			}
			// Deterministic victim: lowest priority, then oldest, tie-break on SequenceID
			sort.Slice(activeSequences, func(i, j int) bool {
				if activeSequences[i].Priority != activeSequences[j].Priority {
					return activeSequences[i].Priority < activeSequences[j].Priority
				}
				if activeSequences[i].Allocated != activeSequences[j].Allocated {
					return activeSequences[i].Allocated > activeSequences[j].Allocated
				}
				return activeSequences[i].SequenceID < activeSequences[j].SequenceID
			})
			return activeSequences[0].SequenceID, nil
		},
	}
	alloc, err := NewElasticBlockAllocator(cfg)
	if err != nil {
		return nil, err
	}

	return &ContinuousBatchStateMachine{
		cfg:            cfg,
		allocator:      alloc,
		maxBlocks:      initialBlocks,
		blockTokens:    blockTokens,
		maxRunning:     maxRunning,
		activeSessions: make(map[string]*fuzzSession),
		allSessions:    make(map[string]*fuzzSession),
	}, nil
}

// Apply executes a single fuzz action and verifies strict invariants post-execution.
func (sm *ContinuousBatchStateMachine) Apply(act FuzzAction) error {
	sm.mu.Lock()
	defer sm.mu.Unlock()

	switch act.Kind {
	case ActionAdmit:
		if err := sm.applyAdmitLocked(act); err != nil {
			return fmt.Errorf("applyAdmit: %w", err)
		}
	case ActionStep:
		if err := sm.applyStepLocked(); err != nil {
			return fmt.Errorf("applyStep: %w", err)
		}
	case ActionPreempt:
		if err := sm.applyPreemptLocked(act.Mode); err != nil {
			return fmt.Errorf("applyPreempt: %w", err)
		}
	case ActionDrain:
		if err := sm.applyDrainLocked(act.TargetBlocks); err != nil {
			return fmt.Errorf("applyDrain: %w", err)
		}
	case ActionSwap:
		if err := sm.applySwapLocked(act.SessionID); err != nil {
			return fmt.Errorf("applySwap: %w", err)
		}
	case ActionEvict:
		if err := sm.applyEvictLocked(act.SessionID); err != nil {
			return fmt.Errorf("applyEvict: %w", err)
		}
	case ActionCancel:
		if err := sm.applyCancelLocked(act.SessionID); err != nil {
			return fmt.Errorf("applyCancel: %w", err)
		}
	case ActionResize:
		if err := sm.applyResizeLocked(act.TargetBlocks); err != nil {
			return fmt.Errorf("applyResize: %w", err)
		}
	}

	// Invariant Verification at every step
	return sm.verifyInvariantsLocked()
}

func (sm *ContinuousBatchStateMachine) applyAdmitLocked(act FuzzAction) error {
	if existing, ok := sm.allSessions[act.SessionID]; ok {
		// Cannot admit an already active or terminal session
		if existing.state != StateCancelled && existing.state != StateCompleted {
			return nil
		}
	}

	ctx, cancel := context.WithCancel(context.Background())
	sess := &fuzzSession{
		id:            act.SessionID,
		state:         StateWaiting,
		priority:      act.Priority,
		promptTokens:  append([]int(nil), act.PromptTokens...),
		emittedTokens: nil,
		maxGen:        4 + (len(act.PromptTokens) % 8),
		ownedBlocks:   make(map[int]bool),
		cancelFunc:    cancel,
		createdStep:   sm.stepCount,
		lastStep:      sm.stepCount,
	}
	_ = ctx // held in sess

	if err := sm.allocator.RegisterSequence(sess.id, sess.priority); err != nil {
		cancel()
		return err
	}

	sm.activeSessions[sess.id] = sess
	sm.allSessions[sess.id] = sess

	// Check if immediate promotion is allowed
	sm.rebalanceRunningSetLocked()
	return nil
}

func (sm *ContinuousBatchStateMachine) applyStepLocked() error {
	sm.stepCount++

	// 1. Check completed or cancelled sessions
	running := sm.getSessionsByStateLocked(StateRunning)
	for _, sess := range running {
		sess.lastStep = sm.stepCount
		// Advance one token
		tok := len(sess.emittedTokens) + 1
		sess.emittedTokens = append(sess.emittedTokens, tok)

		// Check if we need more blocks
		totalTokens := len(sess.promptTokens) + len(sess.emittedTokens)
		neededBlocks := (totalTokens + sm.blockTokens - 1) / sm.blockTokens
		for len(sess.ownedBlocks) < neededBlocks {
			blkID, err := sm.allocator.AllocBlock(sess.id)
			if err != nil {
				// Allocation failed (capacity exhausted) -> Preempt or stall
				break
			}
			sess.ownedBlocks[blkID] = true
		}

		if len(sess.emittedTokens) >= sess.maxGen {
			// Session completed legally: StateRunning -> StateCompleted
			if err := sm.finishSessionLocked(sess, StateCompleted); err != nil {
				return err
			}
		}
	}

	// 2. Rebalance and promote waiting sessions FIFO or by priority
	sm.rebalanceRunningSetLocked()
	return nil
}

func (sm *ContinuousBatchStateMachine) applyPreemptLocked(mode NativePreemptionMode) error {
	running := sm.getSessionsByStateLocked(StateRunning)
	if len(running) == 0 {
		return nil
	}

	// Select victim deterministically: lowest priority, then newest createdStep, tie-break on ID
	var victim *fuzzSession
	for _, s := range running {
		if victim == nil ||
			s.priority < victim.priority ||
			(s.priority == victim.priority && s.createdStep > victim.createdStep) ||
			(s.priority == victim.priority && s.createdStep == victim.createdStep && s.id > victim.id) {
			victim = s
		}
	}
	if victim == nil {
		return nil
	}

	// State transition: StateRunning -> StatePreempted
	victim.state = StatePreempted
	if mode == NativePreemptSwap {
		// Mock serialization of KV blocks
		victim.hostKV = []byte(fmt.Sprintf("kv_blob_seq_%s_blocks_%d", victim.id, len(victim.ownedBlocks)))
	} else {
		victim.hostKV = nil
	}

	// Release owned blocks back to pool
	for blkID := range victim.ownedBlocks {
		if err := sm.allocator.FreeBlock(victim.id, blkID); err != nil {
			return err
		}
	}
	victim.ownedBlocks = make(map[int]bool)

	return nil
}

func (sm *ContinuousBatchStateMachine) applyDrainLocked(targetBlocks int) error {
	if targetBlocks <= 0 {
		targetBlocks = 1
	}
	// Request progressive drain
	if err := sm.allocator.RequestDrain(targetBlocks); err != nil {
		if err == ErrInvalidTargetBlocks {
			return nil
		}
		return err
	}
	sm.maxBlocks = sm.allocator.Stats().TargetBlocks

	// Step progressive drain
	done, err := sm.allocator.ProgressDrain()
	if err != nil {
		return err
	}
	_ = done

	// If allocator preempted sequences via victim selector, reconcile activeSessions
	for id, sess := range sm.activeSessions {
		if _, exists := sm.allocator.sequences[id]; !exists {
			// Preempted and removed by allocator
			sess.state = StatePreempted
			sess.ownedBlocks = make(map[int]bool)
		}
	}
	return nil
}

func (sm *ContinuousBatchStateMachine) applySwapLocked(sessionID string) error {
	sess, ok := sm.activeSessions[sessionID]
	if !ok {
		return nil
	}

	if sess.state == StateRunning {
		// Swap Out: StateRunning -> StatePreempted
		sess.state = StatePreempted
		sess.hostKV = []byte(fmt.Sprintf("swapped_%s", sess.id))
		for blkID := range sess.ownedBlocks {
			if err := sm.allocator.FreeBlock(sess.id, blkID); err != nil {
				return err
			}
		}
		sess.ownedBlocks = make(map[int]bool)
	} else if sess.state == StatePreempted {
		// Swap In / Readmit: StatePreempted -> StateWaiting or StateRunning
		// Re-register sequence if it was unregistered during drain
		if _, exists := sm.allocator.sequences[sess.id]; !exists {
			if err := sm.allocator.RegisterSequence(sess.id, sess.priority); err != nil {
				return err
			}
		}
		// Check capacity
		totalTokens := len(sess.promptTokens) + len(sess.emittedTokens)
		neededBlocks := (totalTokens + sm.blockTokens - 1) / sm.blockTokens
		if sm.allocator.Stats().FreeBlocks >= neededBlocks {
			for i := 0; i < neededBlocks; i++ {
				blkID, err := sm.allocator.AllocBlock(sess.id)
				if err != nil {
					break
				}
				sess.ownedBlocks[blkID] = true
			}
			sess.hostKV = nil
			sess.state = StateRunning
		} else {
			sess.state = StateWaiting
		}
	}
	return nil
}

func (sm *ContinuousBatchStateMachine) applyEvictLocked(sessionID string) error {
	sess, ok := sm.activeSessions[sessionID]
	if !ok {
		// Pick any non-terminal session
		for _, s := range sm.activeSessions {
			sess = s
			break
		}
		if sess == nil {
			return nil
		}
	}

	// State transition: any active state -> StateCancelled
	return sm.finishSessionLocked(sess, StateCancelled)
}

func (sm *ContinuousBatchStateMachine) applyCancelLocked(sessionID string) error {
	sess, ok := sm.activeSessions[sessionID]
	if !ok {
		return nil
	}
	sess.cancelFunc()
	return sm.finishSessionLocked(sess, StateCancelled)
}

func (sm *ContinuousBatchStateMachine) applyResizeLocked(targetBlocks int) error {
	if targetBlocks <= 0 {
		return nil
	}
	curTotal := sm.allocator.Stats().CurrentTotalBlocks
	if targetBlocks > curTotal {
		if err := sm.allocator.Expand(targetBlocks); err != nil {
			return err
		}
		sm.maxBlocks = targetBlocks
	} else if targetBlocks < curTotal {
		if err := sm.allocator.RequestDrain(targetBlocks); err != nil {
			return err
		}
		_, err := sm.allocator.ProgressDrain()
		if err != nil {
			return err
		}
		// If allocator preempted sequences via victim selector, reconcile activeSessions
		for id, sess := range sm.activeSessions {
			if _, exists := sm.allocator.sequences[id]; !exists {
				sess.state = StatePreempted
				sess.ownedBlocks = make(map[int]bool)
			}
		}
	}
	return nil
}

func (sm *ContinuousBatchStateMachine) finishSessionLocked(sess *fuzzSession, terminalState RequestLifecycleState) error {
	sess.state = terminalState
	sess.cancelFunc()

	// Unregister from allocator which frees all allocated blocks
	if _, err := sm.allocator.UnregisterSequence(sess.id); err != nil && err != ErrSequenceNotFound {
		return err
	}
	sess.ownedBlocks = make(map[int]bool)
	delete(sm.activeSessions, sess.id)
	return nil
}

func (sm *ContinuousBatchStateMachine) rebalanceRunningSetLocked() {
	running := sm.getSessionsByStateLocked(StateRunning)
	waiting := sm.getSessionsByStateLocked(StateWaiting)

	// Promote waiting -> running if within maxRunning and block capacity
	for _, sess := range waiting {
		if sm.maxRunning > 0 && len(running) >= sm.maxRunning {
			break
		}
		totalTokens := len(sess.promptTokens) + len(sess.emittedTokens)
		neededBlocks := (totalTokens + sm.blockTokens - 1) / sm.blockTokens
		if neededBlocks <= 0 {
			neededBlocks = 1
		}

		if sm.allocator.Stats().FreeBlocks >= neededBlocks {
			for i := 0; i < neededBlocks; i++ {
				blkID, err := sm.allocator.AllocBlock(sess.id)
				if err != nil {
					break
				}
				sess.ownedBlocks[blkID] = true
			}
			sess.state = StateRunning
			running = append(running, sess)
		}
	}
}

func (sm *ContinuousBatchStateMachine) getSessionsByStateLocked(st RequestLifecycleState) []*fuzzSession {
	var out []*fuzzSession
	for _, s := range sm.activeSessions {
		if s.state == st {
			out = append(out, s)
		}
	}
	// Sort deterministically: priority DESC, createdStep ASC, id ASC
	sort.Slice(out, func(i, j int) bool {
		if out[i].priority != out[j].priority {
			return out[i].priority > out[j].priority
		}
		if out[i].createdStep != out[j].createdStep {
			return out[i].createdStep < out[j].createdStep
		}
		return out[i].id < out[j].id
	})
	return out
}

// verifyInvariantsLocked checks the 4 core invariants:
// 1. Disjoint block ownership between active sessions
// 2. Memory quota conservation (allocated_blocks <= current_total_blocks)
// 3. State machine invariants (no orphaned requests, state transitions follow legal graph)
// 4. Elastic allocator invariant (allocated + free == current_total)
func (sm *ContinuousBatchStateMachine) verifyInvariantsLocked() error {
	// Invariant 1 & 2: Disjoint block ownership and memory quota conservation
	blockOwner := make(map[int]string)
	totalAllocatedInSessions := 0

	for seqID, sess := range sm.activeSessions {
		// Active sessions must be in Waiting, Running, or Preempted
		if sess.state != StateWaiting && sess.state != StateRunning && sess.state != StatePreempted {
			return fmt.Errorf("active session %s has illegal active state %v", seqID, sess.state)
		}

		for blkID := range sess.ownedBlocks {
			if otherSeq, exists := blockOwner[blkID]; exists {
				return fmt.Errorf("INVARIANT VIOLATION: block %d concurrently owned by %s and %s",
					blkID, otherSeq, seqID)
			}
			blockOwner[blkID] = seqID
			totalAllocatedInSessions++
		}
	}

	stats := sm.allocator.Stats()
	if totalAllocatedInSessions != stats.AllocatedBlocks {
		return fmt.Errorf("INVARIANT VIOLATION: sum of session blocks (%d) != allocator allocated blocks (%d)",
			totalAllocatedInSessions, stats.AllocatedBlocks)
	}

	if stats.AllocatedBlocks > stats.CurrentTotalBlocks {
		return fmt.Errorf("INVARIANT VIOLATION: quota exceeded: allocated_blocks (%d) > current_total (%d)",
			stats.AllocatedBlocks, stats.CurrentTotalBlocks)
	}

	// Invariant 4: Elastic allocator internal invariants
	if err := sm.allocator.VerifyInvariant(); err != nil {
		return fmt.Errorf("INVARIANT VIOLATION in allocator: %w", err)
	}

	// Invariant 3: Request state machine invariants
	// Validate all registered sessions in allSessions follow legal terminal or active states
	for id, sess := range sm.allSessions {
		switch sess.state {
		case StateWaiting, StateRunning, StatePreempted:
			if _, active := sm.activeSessions[id]; !active {
				return fmt.Errorf("INVARIANT VIOLATION: session %s in active state %v not in active map (orphaned)",
					id, sess.state)
			}
		case StateCancelled, StateCompleted:
			if _, active := sm.activeSessions[id]; active {
				return fmt.Errorf("INVARIANT VIOLATION: terminal session %s in active map", id)
			}
			if len(sess.ownedBlocks) > 0 {
				return fmt.Errorf("INVARIANT VIOLATION: terminal session %s still holds %d blocks",
					id, len(sess.ownedBlocks))
			}
		default:
			return fmt.Errorf("INVARIANT VIOLATION: unknown state %v for session %s", sess.state, id)
		}
	}

	return nil
}

// ContinuousBatchFuzzGenerator produces deterministic sequences of FuzzActions from a seeded PRNG.
type ContinuousBatchFuzzGenerator struct {
	rng        *rand.Rand
	sessionSeq int
}

func NewContinuousBatchFuzzGenerator(seed int64) *ContinuousBatchFuzzGenerator {
	return &ContinuousBatchFuzzGenerator{
		rng: rand.New(rand.NewSource(seed)),
	}
}

func (g *ContinuousBatchFuzzGenerator) NextAction(sm *ContinuousBatchStateMachine) FuzzAction {
	// Weights:
	// Admit: 25%, Step: 35%, Preempt: 10%, Drain: 8%, Swap: 8%, Evict: 5%, Cancel: 5%, Resize: 4%
	roll := g.rng.Intn(100)

	switch {
	case roll < 25:
		g.sessionSeq++
		seqID := fmt.Sprintf("req-%04d", g.sessionSeq)
		promptLen := 1 + g.rng.Intn(32)
		tokens := make([]int, promptLen)
		for i := range tokens {
			tokens[i] = g.rng.Intn(100)
		}
		prio := g.rng.Intn(5)
		return FuzzAction{
			Kind:         ActionAdmit,
			SessionID:    seqID,
			PromptTokens: tokens,
			Priority:     prio,
		}
	case roll < 60:
		return FuzzAction{Kind: ActionStep}
	case roll < 70:
		mode := NativePreemptSwap
		if g.rng.Intn(2) == 1 {
			mode = NativePreemptRecompute
		}
		return FuzzAction{
			Kind: ActionPreempt,
			Mode: mode,
		}
	case roll < 78:
		// Drain to a watermark between 5 and current total
		target := 5 + g.rng.Intn(30)
		return FuzzAction{
			Kind:         ActionDrain,
			TargetBlocks: target,
		}
	case roll < 86:
		seqID := g.pickActiveSession(sm)
		return FuzzAction{
			Kind:      ActionSwap,
			SessionID: seqID,
		}
	case roll < 91:
		seqID := g.pickActiveSession(sm)
		return FuzzAction{
			Kind:      ActionEvict,
			SessionID: seqID,
		}
	case roll < 96:
		seqID := g.pickActiveSession(sm)
		return FuzzAction{
			Kind:      ActionCancel,
			SessionID: seqID,
		}
	default:
		target := 10 + g.rng.Intn(50)
		return FuzzAction{
			Kind:         ActionResize,
			TargetBlocks: target,
		}
	}
}

func (g *ContinuousBatchFuzzGenerator) pickActiveSession(sm *ContinuousBatchStateMachine) string {
	sm.mu.Lock()
	defer sm.mu.Unlock()
	if len(sm.activeSessions) == 0 {
		return ""
	}
	keys := make([]string, 0, len(sm.activeSessions))
	for k := range sm.activeSessions {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys[g.rng.Intn(len(keys))]
}

// TestContinuousBatchFuzzDeterministicPropertyBased validates the state machine
// across multiple seeds, ensuring all invariants hold at every step and execution is reproducible.
func TestContinuousBatchFuzzDeterministicPropertyBased(t *testing.T) {
	seeds := []int64{42, 1337, 20260904, 99999, 0xCAFE}
	const stepsPerSeed = 200

	for _, seed := range seeds {
		t.Run(fmt.Sprintf("Seed_%d", seed), func(t *testing.T) {
			sm, err := newContinuousBatchStateMachine(32, 16, 8)
			if err != nil {
				t.Fatalf("init state machine failed: %v", err)
			}

			gen := NewContinuousBatchFuzzGenerator(seed)
			var history []FuzzAction

			for step := 0; step < stepsPerSeed; step++ {
				action := gen.NextAction(sm)
				history = append(history, action)

				if err := sm.Apply(action); err != nil {
					t.Fatalf("Seed %d failed at step %d on %v: %v\nRecent history: %v",
						seed, step, action, err, history[max(0, len(history)-10):])
				}
			}

			stats := sm.allocator.Stats()
			t.Logf("Seed %d completed %d steps: activeSessions=%d, totalSessions=%d, allocatedBlocks=%d, currentTotal=%d",
				seed, stepsPerSeed, len(sm.activeSessions), len(sm.allSessions), stats.AllocatedBlocks, stats.CurrentTotalBlocks)
		})
	}
}

// TestContinuousBatchFuzzDeterministicReplay verifies that running the exact same seed
// produces an identical sequence of actions, block allocations, and final states.
func TestContinuousBatchFuzzDeterministicReplay(t *testing.T) {
	const seed = 0x5150
	const steps = 150

	runSimulation := func() (string, []string) {
		sm, err := newContinuousBatchStateMachine(24, 16, 4)
		if err != nil {
			t.Fatalf("init failed: %v", err)
		}
		gen := NewContinuousBatchFuzzGenerator(seed)
		var logs []string

		for i := 0; i < steps; i++ {
			act := gen.NextAction(sm)
			if err := sm.Apply(act); err != nil {
				t.Fatalf("step %d failed: %v", i, err)
			}
			logs = append(logs, fmt.Sprintf("step %d: %s | active=%d, alloc=%d", i, act.String(), len(sm.activeSessions), sm.allocator.Stats().AllocatedBlocks))
		}

		stats := sm.allocator.Stats()
		stateSummary := fmt.Sprintf("state=%v,total=%d,alloc=%d,free=%d,active=%d",
			stats.State, stats.CurrentTotalBlocks, stats.AllocatedBlocks, stats.FreeBlocks, stats.ActiveSequences)
		return stateSummary, logs
	}

	summary1, logs1 := runSimulation()
	summary2, logs2 := runSimulation()

	if len(logs1) != len(logs2) {
		t.Fatalf("Log length mismatch: %d vs %d", len(logs1), len(logs2))
	}
	for i := range logs1 {
		if logs1[i] != logs2[i] {
			t.Fatalf("Step %d action mismatch:\nRun1: %s\nRun2: %s", i, logs1[i], logs2[i])
		}
	}
	if summary1 != summary2 {
		t.Fatalf("Replay mismatch summary:\nRun1: %s\nRun2: %s", summary1, summary2)
	}
}

// TestContinuousBatchFuzzNativeSchedulerEndToEnd exercises the live NativeScheduler with
// continuous batching, preemption, and cancellation under pseudorandom workloads.
func TestContinuousBatchFuzzNativeSchedulerEndToEnd(t *testing.T) {
	m := model.NewSynthetic(SyntheticConfig())
	seeds := []int64{777, 10868}

	for _, seed := range seeds {
		t.Run(fmt.Sprintf("Seed_%d", seed), func(t *testing.T) {
			rng := rand.New(rand.NewSource(seed))
			sched := NewNativeScheduler(m)
			defer sched.Close()

			sched.SetMaxRunning(3)
			sched.SetKVPreemptionPolicy(NativePreemptionPolicy{
				Mode:        NativePreemptSwap,
				MaxBlocks:   6,
				BlockTokens: 16,
			})

			numCalls := 8
			calls := make([]*abi.ToolCall, numCalls)
			for i := 0; i < numCalls; i++ {
				calls[i] = &abi.ToolCall{
					Tool: fmt.Sprintf("tool_%d", i),
					Args: abi.Ref{Kind: abi.RefInline, Inline: []byte(fmt.Sprintf(`{"input": %d}`, rng.Intn(100)))},
				}
			}

			// Admit requests concurrently
			reqs := make([]abi.EngineRequest, numCalls)
			ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
			defer cancel()

			for i, c := range calls {
				req, err := sched.Admit(ctx, c)
				if err != nil {
					t.Fatalf("admit %d failed: %v", i, err)
				}
				reqs[i] = req
			}

			// Randomly cancel one request mid-flight to exercise cancellation and KV reclaim
			cancelIdx := rng.Intn(numCalls)
			reqs[cancelIdx].Cancel()

			// Drain token streams
			var wg sync.WaitGroup
			for i, r := range reqs {
				if i == cancelIdx {
					continue
				}
				wg.Add(1)
				go func(idx int, req abi.EngineRequest) {
					defer wg.Done()
					tokChan := req.Tokens()
					for range tokChan {
						// consume
					}
				}(i, r)
			}
			wg.Wait()

			stats := sched.KVPreemptionStats()
			if stats.MaxBlocks != 6 {
				t.Fatalf("expected MaxBlocks=6, got %d", stats.MaxBlocks)
			}
		})
	}
}
